CACHE TABLE dws_search_volume_30d_${grass_region_without_quote} OPTIONS ('storageLevel' 'DISK_ONLY') AS 
SELECT
    trim(lower(keyword)) AS keyword
    ,COUNT(DISTINCT CASE WHEN view_cnt != 0 AND local_date = ${local_date} THEN (device_id, user_id) END) AS search_volume_1d
    ,COUNT(DISTINCT CASE WHEN view_cnt != 0 AND local_date >= date_sub(${local_date}, 6) THEN (device_id, user_id) END) AS search_volume_7d
    ,COUNT(DISTINCT CASE WHEN view_cnt != 0 AND local_date >= date_sub(${local_date}, 29) THEN (device_id, user_id) END) AS search_volume_30d
FROM
    srdi_mart.dws_sr_data_warehouse_search_srp_user_benchmark_1d
WHERE
    local_date BETWEEN date_sub(${local_date}, 29) AND ${local_date}
    AND grass_region = ${grass_region}
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND view_cnt > 0
    AND keyword != ''
    AND keyword is not null
GROUP BY
    1;

