CREATE TEMPORARY VIEW keyword_search_rank_pct_${grass_region_without_quote} AS
SELECT
    keyword
    ,search_volume_1d
    ,RANK() OVER(ORDER BY search_volume_1d DESC) as keyword_search_volume_rank
    ,SUM(search_volume_1d) OVER(ORDER BY search_volume_1d DESC) / sum(search_volume_1d) OVER() AS keyword_cumulative_search_volume_percentile
FROM
    dws_search_volume_30d_${grass_region_without_quote}
WHERE
    search_volume_1d > 0;

--sql_divide_splitter--

CACHE TABLE keyword_search_rank_pct_type_${grass_region_without_quote} OPTIONS ('storageLevel' 'DISK_ONLY') AS
SELECT 
    keyword
    ,search_volume_1d
    ,keyword_search_volume_rank
    ,keyword_cumulative_search_volume_percentile
    ,CASE
        WHEN search_volume_1d = 1 THEN '6.volume=1'
        WHEN keyword_search_volume_rank <= 300 THEN '1.top 300'
        WHEN keyword_cumulative_search_volume_percentile <= 0.2 THEN '2.0%-20%'
        WHEN keyword_cumulative_search_volume_percentile <= 0.5 THEN '3.20%-50%'
        WHEN keyword_cumulative_search_volume_percentile <= 0.8 THEN '4.50%-80%'
        WHEN keyword_cumulative_search_volume_percentile <= 1.0 THEN '5.80%-100%'
        ELSE NULL
    END AS keyword_search_volume_type
FROM
    keyword_search_rank_pct_${grass_region_without_quote};

