CREATE TEMPORARY VIEW dim_keyword_${grass_region_without_quote} AS 
SELECT
    keyword,
    keyword_cluster,
    level1_keyword_category,
    level2_keyword_category
FROM
    (
        SELECT
            *,
            row_number() over (partition by keyword order by local_date DESC) as rn
        FROM
            srdi_mart.dim_sr_data_warehouse_keyword_di
        WHERE 
            local_date BETWEEN date_sub(${local_date}, 29) AND ${local_date}
            AND grass_region = ${grass_region}
    )
