CACHE TABLE dws_keyword_metrics_${grass_region_without_quote} OPTIONS ('storageLevel' 'DISK_ONLY') AS 
SELECT
    a.keyword
    ,keyword_cluster
    ,level1_keyword_category
    ,level2_keyword_category
    ,target_type AS card_type
    ,is_ads
    ,MAX(is_search_1d) AS is_search_1d
    ,MAX(is_search_7d) AS is_search_7d
    ,SUM(IF(is_search_1d = TRUE AND a.user_id > 0, 1, NULL)) AS user_count_1d
    ,SUM(IF(is_search_7d = TRUE AND a.user_id > 0, 1, NULL)) AS user_count_7d
    ,SUM(IF(a.user_id > 0, 1, NULL)) AS user_count_30d
    ,SUM(imp_cnt_1d) AS imp_cnt_1d
    ,SUM(imp_cnt_7d) imp_cnt_7d
    ,SUM(imp_cnt_30d) AS imp_cnt_30d
    ,SUM(click_cnt_1d) AS click_cnt_1d
    ,SUM(click_cnt_7d) click_cnt_7d
    ,SUM(click_cnt_30d) click_cnt_30d
    ,SUM(ppv_cnt_1d) AS ppv_cnt_1d
    ,SUM(ppv_cnt_7d) ppv_cnt_7d
    ,SUM(ppv_cnt_30d) ppv_cnt_30d
    ,SUM(cart_cnt_1d) AS cart_cnt_1d
    ,SUM(cart_cnt_7d) cart_cnt_7d
    ,SUM(cart_cnt_30d) cart_cnt_30d
    ,SUM(order_cnt_1d) AS order_cnt_1d
    ,SUM(order_cnt_7d) AS order_cnt_7d
    ,SUM(order_cnt_30d) AS order_cnt_30d
    ,SUM(gmv_1d) AS gmv_1d
    ,SUM(gmv_7d) AS gmv_7d
    ,SUM(gmv_30d) AS gmv_30d
    ,SUM(pc2_gmv_1d) AS pc2_gmv_1d
    ,SUM(pc2_gmv_7d) AS pc2_gmv_7d
    ,SUM(pc2_gmv_30d) AS pc2_gmv_30d
    ,SUM(IF(imp_cnt_1d > 0 AND a.user_id > 0, 1, NULL)) AS imp_uu_1d
    ,SUM(IF(imp_cnt_7d > 0 AND a.user_id > 0, 1, NULL)) AS imp_uu_7d
    ,SUM(IF(imp_cnt_30d > 0 AND a.user_id > 0, 1, NULL)) AS imp_uu_30d
    ,SUM(IF(click_cnt_1d > 0 AND a.user_id > 0, 1, NULL)) AS click_uu_1d
    ,SUM(IF(click_cnt_7d > 0 AND a.user_id > 0, 1, NULL)) AS click_uu_7d
    ,SUM(IF(click_cnt_30d > 0 AND a.user_id > 0, 1, NULL)) AS click_uu_30d
    ,SUM(IF(ppv_cnt_1d > 0 AND a.user_id > 0, 1, NULL)) AS ppv_uu_1d
    ,SUM(IF(ppv_cnt_7d > 0 AND a.user_id > 0, 1, NULL)) AS ppv_uu_7d
    ,SUM(IF(ppv_cnt_30d > 0 AND a.user_id > 0, 1, NULL)) AS ppv_uu_30d
    ,SUM(IF(cart_cnt_1d > 0 AND a.user_id > 0, 1, NULL)) AS cart_uu_1d
    ,SUM(IF(cart_cnt_7d > 0 AND a.user_id > 0, 1, NULL)) AS cart_uu_7d
    ,SUM(IF(cart_cnt_30d > 0 AND a.user_id > 0, 1, NULL)) AS cart_uu_30d
    ,SUM(IF(order_cnt_1d > 0 AND a.user_id > 0, 1, NULL)) AS order_uu_1d
    ,SUM(IF(order_cnt_7d > 0 AND a.user_id > 0, 1, NULL)) AS order_uu_7d
    ,SUM(IF(order_cnt_30d > 0 AND a.user_id > 0, 1, NULL)) AS order_uu_30d
FROM
    dws_keyword_30d_${grass_region_without_quote} a
    LEFT JOIN dim_keyword_${grass_region_without_quote} b
    ON a.keyword = b.keyword
GROUP BY 1,2,3,4,5,6;

