CREATE TEMPORARY VIEW dws_search_user_cnt_30d_${grass_region_without_quote} AS
SELECT
    keyword
    ,MAX(CASE WHEN card_type = '__ALL__' AND is_ads = '__ALL__' THEN user_count_1d ELSE NULL END) AS user_count_1d
    ,MAX(CASE WHEN card_type = '__ALL__' AND is_ads = '__ALL__' THEN user_count_7d ELSE NULL END)  AS user_count_7d
    ,MAX(CASE WHEN card_type = '__ALL__' AND is_ads = '__ALL__' THEN user_count_30d ELSE NULL END) AS user_count_30d
