INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_keyword_level_metrics_30d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
    ,time_range = 1
)
SELECT
    a.keyword
    ,keyword_cluster
    ,level1_keyword_category
    ,level2_keyword_category
    ,a.is_ads
    ,a.card_type

    ,imp_cnt_1d AS imp_cnt
    ,click_cnt_1d AS click_cnt
    ,ppv_cnt_1d AS ppv_cnt
    ,cart_cnt_1d AS cart_cnt
    ,order_cnt_1d AS order_cnt
    ,gmv_1d AS gmv
    ,pc2_gmv_1d AS pc2_gmv
    
    ,imp_uu_1d AS imp_uu
    ,click_uu_1d AS click_uu
    ,ppv_uu_1d AS ppv_uu
    ,cart_uu_1d AS cart_uu
    ,order_uu_1d AS order_uu
    ,c.search_volume_1d AS search_volume
    ,b.user_count_1d AS user_count
    ,RANK() OVER (PARTITION BY level1_keyword_category, a.is_ads, a.card_type
        ORDER BY c.search_volume_1d DESC) AS search_volume_rank
    ,c.keyword_search_volume_rank AS keyword_search_volume_rank
    ,c.keyword_cumulative_search_volume_percentile as keyword_cumulative_search_volume_percentile
    ,c.keyword_search_volume_type as keyword_search_volume_type
FROM
    dws_keyword_metrics_${grass_region_without_quote} a
LEFT JOIN
    keyword_search_rank_pct_type_${grass_region_without_quote} c
ON
    a.keyword = c.keyword
LEFT JOIN
    dws_search_user_cnt_30d_${grass_region_without_quote} b
ON
    a.keyword = b.keyword
WHERE
    is_search_1d = TRUE;

